CREATE TYPE public.app_role AS ENUM ('admin','master','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.axis_access_users (user_id uuid PRIMARY KEY, email text NOT NULL UNIQUE, nome text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ok','blocked')), invite_digest text, invite_expires_at timestamptz, activated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.axis_access_users TO authenticated;
GRANT ALL ON public.axis_access_users TO service_role;
ALTER TABLE public.axis_access_users ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.axis_menu_permissions (user_id uuid NOT NULL REFERENCES public.axis_access_users(user_id) ON DELETE CASCADE, menu_id text NOT NULL, PRIMARY KEY(user_id,menu_id));
GRANT SELECT ON public.axis_menu_permissions TO authenticated;
GRANT ALL ON public.axis_menu_permissions TO service_role;
ALTER TABLE public.axis_menu_permissions ENABLE ROW LEVEL SECURITY;
INSERT INTO public.axis_access_users(user_id,email,nome,status,activated_at) SELECT id,lower(email),COALESCE((SELECT p.nome FROM public.profiles p WHERE p.id=u.id),''),'ok',now() FROM auth.users u WHERE lower(email)='denis.santana@bensaude.com.br';
INSERT INTO public.user_roles(user_id,role) SELECT user_id,'admin'::public.app_role FROM public.axis_access_users WHERE email='denis.santana@bensaude.com.br';
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.axis_is_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') AND EXISTS(SELECT 1 FROM public.axis_access_users WHERE user_id=_user_id AND status='ok'); $$;
REVOKE ALL ON FUNCTION public.axis_is_admin(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.axis_is_admin(uuid) TO authenticated,service_role;
CREATE FUNCTION public.axis_can_access(_user_id uuid,_menu text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.axis_access_users WHERE user_id=_user_id AND status='ok') AND (public.axis_is_admin(_user_id) OR (_menu <> 'Configurações' AND (public.has_role(_user_id,'master') OR EXISTS(SELECT 1 FROM public.axis_menu_permissions WHERE user_id=_user_id AND menu_id=_menu)))); $$;
REVOKE ALL ON FUNCTION public.axis_can_access(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.axis_can_access(uuid,text) TO authenticated,service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.axis_is_admin(auth.uid()));
CREATE POLICY access_users_read ON public.axis_access_users FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.axis_is_admin(auth.uid()));
CREATE POLICY permissions_read ON public.axis_menu_permissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.axis_is_admin(auth.uid()));
CREATE FUNCTION public.axis_access_snapshot() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('status',COALESCE((SELECT status FROM public.axis_access_users WHERE user_id=auth.uid()),'unassigned'),'role',CASE WHEN public.axis_is_admin(auth.uid()) THEN 'admin' WHEN public.has_role(auth.uid(),'master') THEN 'master' ELSE 'user' END,'permissions',COALESCE((SELECT jsonb_agg(menu_id) FROM public.axis_menu_permissions WHERE user_id=auth.uid()),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.axis_access_snapshot() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.axis_access_snapshot() TO authenticated;
CREATE FUNCTION public.axis_admin_save_user(p_user uuid,p_nome text,p_role text,p_status text,p_permissions text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.axis_is_admin(auth.uid()) THEN RAISE EXCEPTION 'not authorized'; END IF;
IF public.has_role(p_user,'admin') THEN RAISE EXCEPTION 'principal administrator is protected'; END IF;
IF p_role NOT IN ('master','user') OR p_status NOT IN ('ok','pending','blocked') OR length(p_nome)>150 OR cardinality(p_permissions)>200 OR 'Configurações'=ANY(p_permissions) THEN RAISE EXCEPTION 'invalid input'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.axis_access_users WHERE user_id=p_user) THEN RAISE EXCEPTION 'user not found'; END IF;
IF p_status='ok' AND NOT EXISTS(SELECT 1 FROM public.axis_access_users WHERE user_id=p_user AND activated_at IS NOT NULL) THEN RAISE EXCEPTION 'activation required'; END IF;
UPDATE public.axis_access_users SET nome=trim(p_nome),status=p_status,updated_at=now() WHERE user_id=p_user;
DELETE FROM public.user_roles WHERE user_id=p_user;
INSERT INTO public.user_roles(user_id,role) VALUES(p_user,p_role::public.app_role);
DELETE FROM public.axis_menu_permissions WHERE user_id=p_user;
INSERT INTO public.axis_menu_permissions(user_id,menu_id) SELECT p_user,x FROM (SELECT DISTINCT unnest(p_permissions) x) t WHERE length(x) BETWEEN 1 AND 150;
END; $$;
REVOKE ALL ON FUNCTION public.axis_admin_save_user(uuid,text,text,text,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.axis_admin_save_user(uuid,text,text,text,text[]) TO authenticated;
COMMENT ON TABLE public.user_roles IS 'Protected AXIS roles; administrators cannot be assigned through editable profiles or invitation input.';
COMMENT ON TABLE public.axis_access_users IS 'App access enrollment; invitation stores only a digest and expiration, never its bearer link.';